/**
 * The desktop's own bitmaps: the wallpaper, and the taskbar's Start button.
 *
 * The wallpaper is the clip's opening frame at full size, so when the clip starts there is
 * nothing to see happen — the first thing it draws is the picture already on screen. The clip
 * itself is not here: it streams from Mux (see `mux_clip` in inbox_server.ts) rather than
 * being baked in, because an encode small enough to publish was visibly mushy and this is a
 * photograph of a field. If it can't be reached, this frame is what you get, which is a
 * perfectly good wallpaper.
 *
 * Base64 for the same reason as the sounds and the artwork: neither svelte-package nor the
 * CLI's bun build is guaranteed to carry a binary asset through to dist. One literal each
 * rather than wrapped concatenation — thousands of joined operands overflow the stack of
 * anything that has to parse this.
 */

/** A desktop asset: its MIME type, and its bytes base64-encoded. */
export type DesktopAsset = {
	type: string
	data: string
}

/** Desktop bitmaps by name, served at `/__postboi/api/desktop/:name`. */
export const DESKTOP: Record<string, DesktopAsset> = {
	wallpaper: {
		type: "image/jpeg",
		data: "",
	},
	start: {
		type: "image/png",
		data: "",
	},
}
